using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using Staybnb.Data;using Staybnb.Models;using Staybnb.Services;
namespace Staybnb.Controllers;
[Authorize(Roles="Guest,Host")]
public class CheckInController(ApplicationDbContext db,UserManager<ApplicationUser> users,SecureFileStorage storage,ActivityLogger logger,NotificationService notifications):Controller {
 [Authorize(Roles="Guest")] public async Task<IActionResult> Index(int bookingId){var uid=users.GetUserId(User)!;var b=await db.Bookings.Include(b=>b.Property!).ThenInclude(p=>p.CheckInProcess).Include(b=>b.GuestCheckin!).ThenInclude(c=>c.Documents).FirstOrDefaultAsync(b=>b.Id==bookingId&&b.GuestId==uid&&b.Status==WorkflowStatus.Approved);if(b==null)return NotFound();if(b.GuestCheckin==null&&b.Property!.CheckInProcess!=null){b.GuestCheckin=new GuestCheckin{BookingId=b.Id,CheckInProcessId=b.Property.CheckInProcess.Id};db.GuestCheckins.Add(b.GuestCheckin);await db.SaveChangesAsync();}return View(b);}
 [Authorize(Roles="Guest"),HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Upload(int bookingId,string documentType,IFormFile file){var uid=users.GetUserId(User)!;var b=await db.Bookings.Include(b=>b.Property!).ThenInclude(p=>p.CheckInProcess).Include(b=>b.GuestCheckin).FirstOrDefaultAsync(b=>b.Id==bookingId&&b.GuestId==uid&&b.Status==WorkflowStatus.Approved);if(b==null||b.Property!.CheckInProcess==null)return NotFound();if(file==null||file.Length==0){TempData["Error"]="Choose a document.";return RedirectToAction(nameof(Index),new{bookingId});}try{var name=await storage.SavePrivateDocumentAsync(file);if(b.GuestCheckin==null){b.GuestCheckin=new GuestCheckin{BookingId=b.Id,CheckInProcessId=b.Property.CheckInProcess.Id};db.GuestCheckins.Add(b.GuestCheckin);await db.SaveChangesAsync();}db.GuestDocuments.Add(new GuestDocument{GuestCheckinId=b.GuestCheckin.Id,DocumentType=documentType,FileName=name,Status=WorkflowStatus.Submitted});await db.SaveChangesAsync();await logger.LogAsync(uid,"Uploaded check-in document for booking #"+bookingId,"CheckIn");var hostId=b.Property.UserId;await notifications.AddAsync(hostId,"A guest submitted a check-in document","CheckIn","/Host/Documents");}catch(InvalidOperationException ex){TempData["Error"]=ex.Message;}return RedirectToAction(nameof(Index),new{bookingId});}
 [Authorize(Roles="Host"),HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> ReviewDocument(int id,string decision){var uid=users.GetUserId(User)!;var d=await db.GuestDocuments.Include(d=>d.GuestCheckin!).ThenInclude(c=>c.Documents).Include(d=>d.GuestCheckin!).ThenInclude(c=>c.Booking!).ThenInclude(b=>b.Property!).ThenInclude(p=>p.CheckInProcess).Include(d=>d.GuestCheckin!).ThenInclude(c=>c.Booking!).ThenInclude(b=>b.Guest).FirstOrDefaultAsync(d=>d.Id==id&&d.GuestCheckin!.Booking!.Property!.UserId==uid);if(d==null)return NotFound();if(d.Status!=WorkflowStatus.Submitted)return BadRequest("Document already reviewed.");if(decision is not ("verify" or "reject"))return BadRequest();d.Status=decision=="verify"?WorkflowStatus.Verified:WorkflowStatus.NeedsCorrection;d.ReviewedById=uid;d.ReviewedAt=DateTime.UtcNow;var checkin=d.GuestCheckin!;var requiredCount=1;if(checkin.Booking?.Property?.CheckInProcess?.RequiredDocumentsJson is string requiredJson){try{requiredCount=Math.Max(1,System.Text.Json.JsonSerializer.Deserialize<List<string>>(requiredJson)?.Count??1);}catch(System.Text.Json.JsonException){requiredCount=1;}}if(decision=="verify"&&checkin.Documents.Count(x=>x.Status==WorkflowStatus.Verified)>=requiredCount&&checkin.Documents.All(x=>x.Status==WorkflowStatus.Verified)){checkin.Status=WorkflowStatus.Verified;var booking=checkin.Booking!;if(booking.Status==WorkflowStatus.Approved){booking.Status=WorkflowStatus.CheckedIn;await notifications.AddAsync(booking.GuestId,"Your check-in documents were verified","CheckIn",$"/Bookings/Details/{booking.Id}");}}await db.SaveChangesAsync();await logger.LogAsync(uid,$"{decision}d guest document #{id}","CheckIn");return RedirectToAction("Bookings","Host");}
 [Authorize(Roles="Host"),HttpGet] public async Task<IActionResult> DownloadDocument(int id){var uid=users.GetUserId(User)!;var d=await db.GuestDocuments.Include(d=>d.GuestCheckin!).ThenInclude(c=>c.Booking!).ThenInclude(b=>b.Property).FirstOrDefaultAsync(d=>d.Id==id&&d.GuestCheckin!.Booking!.Property!.UserId==uid);if(d==null)return NotFound();var path=storage.PrivateDocumentPath(d.FileName);if(!System.IO.File.Exists(path))return NotFound();return PhysicalFile(path,"application/octet-stream",Path.GetFileName(path));}
}
